PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (   id INTEGER PRIMARY KEY AUTOINCREMENT,   username TEXT NOT NULL UNIQUE,   email TEXT NOT NULL UNIQUE,   password_hash TEXT NOT NULL,   full_name TEXT NOT NULL,   role TEXT NOT NULL DEFAULT 'viewer',   is_active INTEGER NOT NULL DEFAULT 1,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE roles (   id INTEGER PRIMARY KEY AUTOINCREMENT,   name TEXT NOT NULL UNIQUE,   description TEXT,   permissions TEXT NOT NULL DEFAULT '{}',   created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE sessions (   id TEXT PRIMARY KEY,   user_id INTEGER NOT NULL,   expires_at TEXT NOT NULL,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE );
CREATE TABLE branches (   id INTEGER PRIMARY KEY AUTOINCREMENT,   code TEXT NOT NULL UNIQUE,   name TEXT NOT NULL,   full_name TEXT NOT NULL,   city TEXT,   is_active INTEGER NOT NULL DEFAULT 1,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE employees (   id INTEGER PRIMARY KEY AUTOINCREMENT,   full_name TEXT NOT NULL,   branch_id INTEGER,   division TEXT NOT NULL DEFAULT 'FACILITY CARE',   phone TEXT,   join_date TEXT,   status TEXT NOT NULL DEFAULT 'Aktif',   notes TEXT,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')),   FOREIGN KEY (branch_id) REFERENCES branches(id) );
CREATE TABLE contracts (   id INTEGER PRIMARY KEY AUTOINCREMENT,   employee_id INTEGER NOT NULL,   branch_id INTEGER,   division TEXT NOT NULL DEFAULT 'FACILITY CARE',   start_date TEXT NOT NULL,   end_date TEXT NOT NULL,   contract_type TEXT,   pkwt_number TEXT,   status TEXT NOT NULL DEFAULT 'Aktif',   notes TEXT,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')),   FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE,   FOREIGN KEY (branch_id) REFERENCES branches(id) );
CREATE TABLE activity_schedule (   id INTEGER PRIMARY KEY AUTOINCREMENT,   branch_id INTEGER,   activity_type TEXT NOT NULL,   period TEXT NOT NULL,   pic TEXT,   opening_date TEXT,   target_date TEXT,   completion_date TEXT,   status TEXT NOT NULL DEFAULT 'Pending',   notes TEXT,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')),   FOREIGN KEY (branch_id) REFERENCES branches(id) );
CREATE TABLE issues (   id INTEGER PRIMARY KEY AUTOINCREMENT,   report_date TEXT NOT NULL,   branch_id INTEGER,   category TEXT NOT NULL,   source TEXT,   complaint TEXT NOT NULL,   employee_name TEXT,   fc_specialist TEXT,   solution TEXT,   status TEXT NOT NULL DEFAULT 'Open',   completion_date TEXT,   day_count INTEGER,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')),   FOREIGN KEY (branch_id) REFERENCES branches(id) );
CREATE TABLE one_on_one (   id INTEGER PRIMARY KEY AUTOINCREMENT,   meeting_date TEXT NOT NULL,   branch_id INTEGER,   employee_name TEXT NOT NULL,   pic TEXT,   problem TEXT NOT NULL,   solution TEXT,   status TEXT NOT NULL DEFAULT 'Open',   completion_date TEXT,   day_count INTEGER,   document_link TEXT,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')),   FOREIGN KEY (branch_id) REFERENCES branches(id) );
CREATE TABLE training (   id INTEGER PRIMARY KEY AUTOINCREMENT,   training_date TEXT NOT NULL,   batch TEXT,   subject TEXT NOT NULL,   participants TEXT,   branch_id INTEGER,   trainer TEXT,   score REAL,   notes TEXT,   document_link TEXT,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')),   FOREIGN KEY (branch_id) REFERENCES branches(id) );
CREATE TABLE relievers (   id INTEGER PRIMARY KEY AUTOINCREMENT,   branch_id INTEGER,   original_fc_name TEXT,   period TEXT,   reliever_name TEXT NOT NULL,   backup_date TEXT NOT NULL,   completion_date TEXT,   reason TEXT,   shift TEXT,   status TEXT NOT NULL DEFAULT 'Pending',   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')),   FOREIGN KEY (branch_id) REFERENCES branches(id) );
CREATE TABLE inspection_reports (   id INTEGER PRIMARY KEY AUTOINCREMENT,   branch_id INTEGER,   period TEXT NOT NULL,   inspection_date TEXT NOT NULL,   status TEXT NOT NULL DEFAULT 'Pending',   fc_score REAL,   spv_score REAL,   document_link TEXT,   notes TEXT,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')),   FOREIGN KEY (branch_id) REFERENCES branches(id) );
CREATE TABLE cleaning_reports (   id INTEGER PRIMARY KEY AUTOINCREMENT,   branch_id INTEGER,   activity_type TEXT NOT NULL,   period TEXT NOT NULL,   activity_date TEXT NOT NULL,   status TEXT NOT NULL DEFAULT 'Pending',   document_link TEXT,   notes TEXT,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')),   FOREIGN KEY (branch_id) REFERENCES branches(id) );
CREATE TABLE fogging_reports (   id INTEGER PRIMARY KEY AUTOINCREMENT,   branch_id INTEGER,   activity_type TEXT NOT NULL DEFAULT 'Fogging',   period TEXT NOT NULL,   activity_date TEXT,   status TEXT NOT NULL DEFAULT 'Pending',   document_link TEXT,   notes TEXT,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')),   FOREIGN KEY (branch_id) REFERENCES branches(id) );
CREATE TABLE basecamp_reports (   id INTEGER PRIMARY KEY AUTOINCREMENT,   branch_id INTEGER,   problem TEXT NOT NULL,   pic TEXT,   info_date TEXT NOT NULL,   done_date TEXT,   status TEXT NOT NULL DEFAULT 'Open',   notes TEXT,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')),   FOREIGN KEY (branch_id) REFERENCES branches(id) );
CREATE TABLE sop (   id INTEGER PRIMARY KEY AUTOINCREMENT,   name TEXT NOT NULL,   category TEXT NOT NULL,   document_link TEXT,   version TEXT,   effective_date TEXT,   notes TEXT,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE master_checklist (   id INTEGER PRIMARY KEY AUTOINCREMENT,   name TEXT NOT NULL,   category TEXT,   document_link TEXT,   description TEXT,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE master_forms (   id INTEGER PRIMARY KEY AUTOINCREMENT,   name TEXT NOT NULL,   category TEXT,   document_link TEXT,   description TEXT,   is_public INTEGER NOT NULL DEFAULT 0,   created_at TEXT NOT NULL DEFAULT (datetime('now')),   updated_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE supply_requests (   id INTEGER PRIMARY KEY AUTOINCREMENT,   submitted_at TEXT NOT NULL DEFAULT (datetime('now')),   submitter_name TEXT,   branch_id INTEGER,   branch_name TEXT,   tools_items TEXT,   tools_quantity TEXT,   chemical_items TEXT,   chemical_quantity TEXT,   additional_notes TEXT,   status TEXT NOT NULL DEFAULT 'Pending',   processed_by TEXT,   processed_at TEXT,   FOREIGN KEY (branch_id) REFERENCES branches(id) );
CREATE TABLE pic_list (   id INTEGER PRIMARY KEY AUTOINCREMENT,   name TEXT NOT NULL UNIQUE,   role TEXT,   is_active INTEGER NOT NULL DEFAULT 1 );
CREATE TABLE sp_data (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          tanggal TEXT,
          employee_name TEXT NOT NULL,
          branch_id INTEGER,
          sp_type TEXT,
          status TEXT DEFAULT 'Aktif',
          document_link TEXT,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP, division TEXT, akhir_sp TEXT,
          FOREIGN KEY (branch_id) REFERENCES branches(id)
        );
CREATE TABLE mutasi_data (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          tanggal TEXT,
          employee_name TEXT NOT NULL,
          from_branch_id INTEGER,
          to_branch_id INTEGER,
          status TEXT DEFAULT 'Proses',
          document_link TEXT,
          created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
          FOREIGN KEY (from_branch_id) REFERENCES branches(id),
          FOREIGN KEY (to_branch_id) REFERENCES branches(id)
        );
CREATE TABLE test_audit (id INTEGER PRIMARY KEY);
CREATE TABLE audit_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    request_id TEXT,
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
    execution_time_ms REAL,
    user_id INTEGER,
    username TEXT,
    role TEXT,
    module TEXT,
    action TEXT,
    record_id TEXT,
    old_value TEXT, -- JSON
    new_value TEXT, -- JSON
    ip_address TEXT,
    user_agent TEXT,
    status TEXT,
    remarks TEXT,
    FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE TABLE timeline_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
    module TEXT,
    title TEXT,
    description TEXT,
    user_name TEXT,
    icon TEXT,
    link TEXT
);
CREATE TABLE rbac_roles (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    description TEXT
);
CREATE TABLE rbac_permissions (
    id TEXT PRIMARY KEY,
    module TEXT NOT NULL,
    action TEXT NOT NULL, -- e.g., 'read', 'create', 'update', 'delete'
    description TEXT
);
CREATE TABLE rbac_role_permissions (
    role_id TEXT,
    permission_id TEXT,
    PRIMARY KEY(role_id, permission_id),
    FOREIGN KEY(role_id) REFERENCES rbac_roles(id) ON DELETE CASCADE,
    FOREIGN KEY(permission_id) REFERENCES rbac_permissions(id) ON DELETE CASCADE
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_supply_requests_status
  ON supply_requests(status);
CREATE INDEX idx_basecamp_reports_status
  ON basecamp_reports(status);
CREATE INDEX idx_audit_module ON audit_logs(module);
CREATE INDEX idx_audit_request ON audit_logs(request_id);
CREATE INDEX idx_audit_user ON audit_logs(user_id);
CREATE INDEX idx_audit_timestamp ON audit_logs(timestamp);
CREATE INDEX idx_timeline_timestamp ON timeline_events(timestamp DESC);
